// state: (cur, prev) where prev=0 means no previous (1-indexed rooms)
// encode state as cur*(N+1)+prev, cur in [1..N], prev in [0..N]
int dist[MAXN][MAXN]; // dist[cur][prev]
int color[MAXN][MAXN]; // 0=white,1=gray,2=black
int has_cycle;

void dfs(int cur, int prev) {
    color[cur][prev] = 1;
    int moved = 0;
    for (int next = 1; next <= N; next++) {
        if (adj[cur][next] && next != prev) {
            moved = 1;
            if (color[next][cur] == 1) { has_cycle = 1; return; }
            if (color[next][cur] == 0) dfs(next, cur);
            if (has_cycle) return;
            if (dist[next][cur] == -2) { has_cycle = 1; return; } // infinite
            if (dist[cur][prev] < dist[next][cur] + 1)
                dist[cur][prev] = dist[next][cur] + 1;
        }
    }
    if (!moved) dist[cur][prev] = 0;
    color[cur][prev] = 2;
}

int main() {
    scanf("%d %d", &N, &M);
    for (int i = 0; i < M; i++) {
        int a, b; scanf("%d %d", &a, &b);
