    }
    memset(dist, -2, sizeof(dist)); // -2 = uncomputed
    memset(color, 0, sizeof(color));
    has_cycle = 0;
    int ans = 0;
    for (int r = 1; r <= N && !has_cycle; r++) {
        if (color[r][0] == 0) dfs(r, 0);
