#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int to;
    int next;
} Edge;

static int max(int a, int b) { return a > b ? a : b; }

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    /* Build directed graph and reverse graph */
    Edge *edges = (Edge *)malloc(sizeof(Edge) * m);
    Edge *redges = (Edge *)malloc(sizeof(Edge) * m);
    int *head = (int *)malloc(sizeof(int) * n);
    int *rhead = (int *)malloc(sizeof(int) * n);
    int *outdeg = (int *)calloc(n, sizeof(int));

    for (int i = 0; i < n; i++) head[i] = rhead[i] = -1;

    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u; --v;

        edges[i].to = v;
        edges[i].next = head[u];
        head[u] = i;

        redges[i].to = u;
        redges[i].next = rhead[v];
        rhead[v] = i;

        outdeg[u]++;
    }

    /*
      State = directed edge (prev -> cur), meaning George is in cur
      and came from prev, so he may choose any outgoing edge from cur
      except cur -> prev.
      Also initial states are rooms without previous room.

      If from some initial room George can avoid confinement forever,
      answer is Infinite.

      A state (prev, cur) is terminal if cur has no allowed move:
      allowed count = outdeg[cur] - (exists edge cur->prev ? 1 : 0)
      but since state exists only if prev->cur is an edge, immediate return
      is forbidden only along cur->prev if that edge exists.

      We solve on edge-states:
      dp(prev->cur) = 1 + max dp(cur->next) over next != prev and edge cur->next exists.
      Infinite iff there is a reachable cycle in state graph from some initial room.

      Observation:
      State graph nodes are original directed edges.
      Transition: (a->b) -> (b->c) for every edge b->c with c != a.

      We need:
      1) detect any cycle reachable from some initial room:
         initial room s can move to any edge s->x, so any edge-state is reachable
         from an initial room iff its tail is reachable as first step from some room,
         i.e. every edge-state is reachable by choosing initial room = its tail.
         Therefore if state graph has any cycle at all, answer is Infinite.
      2) otherwise compute longest path considering also first move from initial room.
         From room s, time until confinement:
           if outdeg[s]==0 => 0
           else 1 + max dp(s->x)
         answer is max over s.
    */

    /* Build state graph over m edge-states */
    int *shead = (int *)malloc(sizeof(int) * m);   /* outgoing transitions from state */
    int *rshead = (int *)malloc(sizeof(int) * m);  /* reverse transitions */
    for (int i = 0; i < m; i++) shead[i] = rshead[i] = -1;

    /* Worst-case transitions can be large; build dynamically */
    long long cap = (m > 0 ? 4LL * m : 1LL);
    Edge *sedges = (Edge *)malloc(sizeof(Edge) * cap);
    Edge *rsedges = (Edge *)malloc(sizeof(Edge) * cap);
    long long scnt = 0;

    /* To test existence of edge u->v quickly, store adjacency lists only; not needed explicitly.
       For each state i: let i be a->b. Transitions to all edges b->c with c != a.
    */
    int *from = (int *)malloc(sizeof(int) * m);
    int *to = (int *)malloc(sizeof(int) * m);
    for (int i = 0; i < m; i++) {
        /* Recover original edge endpoints */
        /* edge i is from some u where i is in head[u], but we stored only to.
           Need tails; fill while reading would have been easier.
        */
    }

    /* Re-read tails by traversing adjacency */
    for (int u = 0; u < n; u++) {
        for (int e = head[u]; e != -1; e = edges[e].next) {
            from[e] = u;
            to[e] = edges[e].to;
        }
    }

    for (int i = 0; i < m; i++) {
        int a = from[i], b = to[i];
        (void)a;
        for (int e = head[b]; e != -1; e = edges[e].next) {
            int c = edges[e].to;
            if (c == from[i]) continue; /* immediate return forbidden */
            if (scnt >= cap) {
                cap *= 2;
                sedges = (Edge *)realloc(sedges, sizeof(Edge) * cap);
                rsedges = (Edge *)realloc(rsedges, sizeof(Edge) * cap);
            }
            sedges[scnt].to = e;
            sedges[scnt].next = shead[i];
            shead[i] = (int)scnt;

            rsedges[scnt].to = i;
            rsedges[scnt].next = rshead[e];
            rshead[e] = (int)scnt;

            scnt++;
        }
    }

    /* Kahn on state graph to detect cycle and compute longest path on DAG */
    int *deg = (int *)calloc(m, sizeof(int));
    for (int i = 0; i < m; i++) {
        for (int e = shead[i]; e != -1; e = sedges[e].next) deg[sedges[e].to]++;
    }

    int *q = (int *)malloc(sizeof(int) * (m > 0 ? m : 1));
    int qh = 0, qt = 0;
    for (int i = 0; i < m; i++) if (deg[i] == 0) q[qt++] = i;

    int *topo = (int *)malloc(sizeof(int) * (m > 0 ? m : 1));
    int tcnt = 0;
    while (qh < qt) {
        int v = q[qh++];
        topo[tcnt++] = v;
        for (int e = shead[v]; e != -1; e = sedges[e].next) {
            int w = sedges[e].to;
            if (--deg[w] == 0) q[qt++] = w;
        }
    }

    if (tcnt < m) {
        printf("Infinite\n");
        return 0;
    }

    /* Longest path in DAG of states:
       dp[state] = number of further moves possible starting from this state
       before confinement, counting moves AFTER arriving in current room.
       If no outgoing transitions, dp=0.
       Else dp = 1 + max(dp[next]).
    */
    int *dp = (int *)calloc(m, sizeof(int));
    for (int idx = m - 1; idx >= 0; idx--) {
        int v = topo[idx];
        int best = 0;
        for (int e = shead[v]; e != -1; e = sedges[e].next) {
            int w = sedges[e].to;
            best = max(best, 1 + dp[w]);
        }
        dp[v] = best;
    }

    int ans = 0;
    for (int s = 0; s < n; s++) {
        if (outdeg[s] == 0) {
            ans = max(ans, 0);
        } else {
            int best = 0;
            for (int e = head[s]; e != -1; e = edges[e].next) {
                best = max(best, 1 + dp[e]); /* first move */
            }
            ans = max(ans, best);
        }
    }

    printf("%d\n", ans);

    return 0;
}

