    vector<pair<int,int>> edges;
    edges.reserve(m);

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        out[a].push_back(b);
        in[b].push_back(a);
        edges.push_back({a, b});
    }

    // If there exists a directed cycle, George can keep moving forever.
    vector<int> indeg(n, 0);
    for (auto &e : edges) indeg[e.second]++;

    queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (indeg[i] == 0) q.push(i);
    }

    int removed = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        removed++;
        for (int v : out[u]) {
            if (--indeg[v] == 0) q.push(v);
        }
    }

    if (removed < n) {
        cout << "Infinite\n";
        return 0;
    }

    // DAG: longest possible number of moves before reaching a sink.
    // DP from sinks backwards.
    vector<int> dp(n, 0); // max moves starting from room u
    vector<int> outdeg(n);
    for (int i = 0; i < n; ++i) outdeg[i] = (int)out[i].size();

    queue<int> q2;
    for (int i = 0; i < n; ++i) {
        if (outdeg[i] == 0) q2.push(i);
    }

    while (!q2.empty()) {
        int u = q2.front();
        q2.pop();
        for (int p : in[u]) {
            dp[p] = max(dp[p], dp[u] + 1);
            if (--outdeg[p] == 0) q2.push(p);
        }
    }

    int ans = 0;
    for (int i = 0; i < n; ++i) ans = max(ans, dp[i]);
    cout << ans << '\n';

    return 0;
}

import java.util.*;

public class MonkeyEscape {
    static List<Integer>[] graph;
    static int[][] memo;
    static boolean[][] visited;
    static boolean[][] inStack;
    static boolean infinite;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            graph[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            graph[u].add(v);
        }

        memo = new int[n][n];
        for (int[] row : memo) Arrays.fill(row, -1);
        visited = new boolean[n][n];
        inStack = new boolean[n][n];
        infinite = false;

        int maxSteps = 0;
        for (int start = 0; start < n; start++) {
            for (int prev = 0; prev < n; prev++) {
                if (prev != start || start == -1) {
                    maxSteps = Math.max(maxSteps, dfs(start, prev));
                }
            }
        }

        if (infinite) {
            System.out.println("Infinite");
        } else {
            System.out.println(maxSteps);
        }
        sc.close();
    }

    static int dfs(int curr, int prev) {
        if (infinite) return 0;
        if (inStack[curr][prev]) {
            infinite = true;
            return 0;
        }
        if (visited[curr][prev]) {
            return memo[curr][prev];
        }

        visited[curr][prev] = true;
        inStack[curr][prev] = true;
        int maxLen = 0;

        for (int next : graph[curr]) {
            if (next == prev) continue;
            maxLen = Math.max(maxLen, 1 + dfs(next, curr));
        }

        inStack[curr][prev] = false;
        memo[curr][prev] = maxLen;
        return maxLen;
    }
}

