public class Main {
    static List<Integer>[] adj;
    static int[] dp; // dp for state index
    static int[] color;
    static boolean infinite = false;
    static int N;

    static int stateId(int cur, int prev) {
        // prev from -1 to N-1, map -1 to N
        return cur * (N + 1) + (prev + 1);
    }

    static int dfs(int cur, int prev) {
        int sid = stateId(cur, prev);
        if (color[sid] == 1) { infinite = true; return 0; }
        if (color[sid] == 2) return dp[sid];
        color[sid] = 1;
        int best = -1; // -1 means no moves
        for (int next : adj[cur]) {
            if (next == prev) continue;
            int val = dfs(next, cur);
            if (infinite) return 0;
            best = Math.max(best, val);
        }
        color[sid] = 2;
        dp[sid] = (best == -1) ? 0 : best + 1;
        return dp[sid];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        int M = sc.nextInt();
        adj = new ArrayList[N];
        for (int i = 0; i < N; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < M; i++) {
            int u = sc.nextInt() - 1, v = sc.nextInt() - 1;
            adj[u].add(v);
        }
        int totalStates = N * (N + 1);
        dp = new int[totalStates];
        color = new int[totalStates];
        int ans = 0;
        for (int start = 0; start < N; start++) {
            if (adj[start].isEmpty()) continue;
            int val = dfs(start, -1);
            if (infinite) { System.out.println("Infinite"); return; }
            ans = Math.max(ans, val);
        }
        System.out.println(ans);
    }
}

