public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        int m = fs.nextInt();

        List<Integer>[] g = new ArrayList[n];
        int[] indeg = new int[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            g[u].add(v);
            indeg[v]++;
        }

        // Kahn: detect cycle and get topological order.
        int[] q = new int[n];
        int head = 0, tail = 0;
        for (int i = 0; i < n; i++) if (indeg[i] == 0) q[tail++] = i;

        int[] topo = new int[n];
        int t = 0;
        while (head < tail) {
            int u = q[head++];
            topo[t++] = u;
            for (int v : g[u]) {
                if (--indeg[v] == 0) q[tail++] = v;
            }
        }

        if (t < n) {
            System.out.println("Infinite");
            return;
        }

        long[] dp = new long[n]; // longest path starting at u
        long ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            int u = topo[i];
            long best = 0;
            for (int v : g[u]) {
                best = Math.max(best, 1 + dp[v]);
            }
            dp[u] = best;
            ans = Math.max(ans, best);
        }

        System.out.println(ans);
    }
}

import sys
sys.setrecursionlimit(10**6)

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    n = int(next(it))
    m = int(next(it))
    adj = [[] for _ in range(n)]
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        adj[u].append(v)

    # Cycle detection
    state = [0] * n  # 0=unvisited, 1=visiting, 2=visited
    has_cycle = False

    def dfs(u):
        nonlocal has_cycle
        state[u] = 1
        for v in adj[u]:
            if state[v] == 1:
                has_cycle = True
                return
            elif state[v] == 0:
                dfs(v)
                if has_cycle:
                    return
        state[u] = 2

    for i in range(n):
        if state[i] == 0:
            dfs(i)
            if has_cycle:
                print("Infinite")
                return

    # No cycle -> longest path in DAG
    dp = [0] * n
    visited = [False] * n

    def longest(u):
        if visited[u]:
            return dp[u]
        visited[u] = True
        best = 0
        for v in adj[u]:
            best = max(best, longest(v))
        dp[u] = best + 1
        return dp[u]

    ans = 0
    for i in range(n):
        ans = max(ans, longest(i))
    print(ans)

if __name__ == "__main__":
    solve()
